/**
 * Mihomo 全局覆写脚本，适用于 Clash Party / Clash Verge Rev
 *
 * 宿主程序会调用 main(config)，传入订阅解析后的配置对象。
 * 本脚本在该对象上合并或替换配置，最后必须返回处理后的对象。
 */

const ONE_DAY = 24 * 60 * 60;

// 额外订阅占位：使用前请替换 URL，切勿把真实订阅凭据提交到公开仓库。
const additionalProxyProviders = {
  "p1": {
    "type": "http",
    "url": "https://www.1.com",
    "interval": ONE_DAY,
    "override": {
      "additional-prefix": "p1 |"
    }
  },
  "p2": {
    "type": "http",
    "url": "https://www.2.com",
    "interval": ONE_DAY,
    "override": {
      "additional-prefix": "p2 |"
    }
  }
};

const generalConfig = {
  "mixed-port": 7890,
  "allow-lan": true,
  "bind-address": "*",
  "ipv6": true,
  "unified-delay": true
};

function isRecord(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function assertHasProxySource(config) {
  const proxyCount = Array.isArray(config.proxies) ? config.proxies.length : 0;
  const providers = isRecord(config["proxy-providers"])
    ? config["proxy-providers"]
    : {};
  const additionalProviderCount = Object.keys(additionalProxyProviders).length;

  if (proxyCount === 0 && Object.keys(providers).length === 0 && additionalProviderCount === 0) {
    throw new Error("配置文件中未找到任何代理");
  }
}

// 程序入口
function main(config) {
  if (!isRecord(config)) {
    throw new TypeError("main(config) 需要接收一个配置对象");
  }

  assertHasProxySource(config);

  const originalProviders = isRecord(config["proxy-providers"])
    ? config["proxy-providers"]
    : {};

  // 合并而非覆盖
  config["proxy-providers"] = {
    ...originalProviders,
    ...additionalProxyProviders
  };

  // 这些字段采用“完全替换”策略，确保最终行为由本脚本统一控制。
  config.dns = dnsConfig;
  config["proxy-groups"] = proxyGroupConfig;
  config["rule-providers"] = ruleProviders;
  config.rules = rules;

  Object.assign(config, generalConfig);

  return config;
}
