// 代理组：共同字段集中维护，差异字段放入下方的数据表。
const ICON_BASE = "https://cdn.jsdelivr.net/gh/Koolson/Qure@master/IconSet/Color";
const NODE_EXCLUDE_PATTERN = "(?i)GB|Traffic|Expire|Premium|频道|订阅|ISP|流量|到期|重置";
const REGION_ORDER = ["HK", "TW", "JP", "KR", "US", "DE", "SG", "FR", "UK"];

const groupBaseOption = {
  "interval": 300,
  "timeout": 3000,
  "url": "https://www.gstatic.com/generate_204",
  "max-failed-times": 3,
  "hidden": false
};

function createSelectGroup(name, proxies, icon) {
  return {
    ...groupBaseOption,
    name,
    "type": "select",
    // 每个组都拿到独立数组，避免宿主修改一个组时连带影响其他组。
    "proxies": [...proxies],
    "include-all": true,
    "exclude-filter": NODE_EXCLUDE_PATTERN,
    icon
  };
}

function createRegionGroup({ name, filter, icon, excludeFilter }) {
  const group = {
    ...groupBaseOption,
    name,
    "type": "url-test",
    "include-all": true,
    filter
  };

  if (excludeFilter) {
    group["exclude-filter"] = excludeFilter;
  }

  group.tolerance = 50;
  group.icon = `${ICON_BASE}/${icon}`;
  return group;
}

