// 规则集通用配置
const ruleProviderCommon = {
  "type": "http",
  "format": "yaml",
  "interval": ONE_DAY,
  "proxy": "Proxy"
};

const BLACKMATRIX_RULE_BASE =
  "https://cdn.jsdelivr.net/gh/blackmatrix7/ios_rule_script@master/rule/Clash";

function createRuleProvider(name, url) {
  return {
    ...ruleProviderCommon,
    "behavior": "classical",
    url,
    "path": `./ruleset/${name}.yaml`
  };
}

function createBlackmatrixRuleProvider(name, remoteName = name, fileName = `${remoteName}.yaml`) {
  const url = `${BLACKMATRIX_RULE_BASE}/${remoteName}/${fileName}`;
  return createRuleProvider(name, url);
}

const blackmatrixRuleDefinitions = [
  ["Apple", "Apple", "Apple_Classical.yaml"],
  ["Telegram"],
  ["YouTube"],
  ["BiliBili"],
  ["TikTok"],
  ["Spotify"],
  ["Netflix"],
  ["Disney"],
  ["Google"],
  ["OpenAI"],
  ["Microsoft"],
  ["Twitter"],
  ["Steam"],
  ["OneDrive"],
  ["Emby"],
  ["Gemini"],
  ["Claude"],
  ["Github", "GitHub", "GitHub_No_Resolve.yaml"],
  ["Global"],
  ["China"]
];

// 规则集名称是 rules 中 RULE-SET 的外键；改名时两边必须同步。
const ruleProviders = Object.fromEntries(
  blackmatrixRuleDefinitions.map((definition) => {
    const [name] = definition;
    return [name, createBlackmatrixRuleProvider(...definition)];
  })
);

function parseRuleLines(text) {
  return text
    .trim()
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
}

function getRulePolicy(rule) {
  const fields = rule.split(",");
  const type = fields[0];

  if (type === "MATCH") return fields[1];
  if (["AND", "OR", "NOT"].includes(type)) return fields[fields.length - 1];
  return fields[2];
}

function dedupeRules(ruleList) {
  return [...new Set(ruleList)];
}

